        # Divisors
        for div in [2, 3, 4, 5, 6]:
            if size % div == 0:
                exps.add(size // div)
                exps.add(2 * (size // div) % size)
        # Units
        units = [u for u in range(1, size) if math.gcd(u, size) == 1]
